import { ref } from 'vue'

export type Theme = 'light' | 'dark'

const STORAGE_KEY = 'agent-hub.theme'
const theme = ref<Theme>('light')

function readInitial(): Theme {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY)
    if (stored === 'light' || stored === 'dark') return stored
  } catch {
    // localStorage 不可用时退回系统偏好。
  }
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

export function applyTheme(next: Theme): void {
  theme.value = next
  document.documentElement.dataset.theme = next
  document.documentElement.classList.toggle('dark', next === 'dark')
  try {
    window.localStorage.setItem(STORAGE_KEY, next)
  } catch {
    // 忽略隐私模式写入失败。
  }
}

export function useTheme() {
  function toggle(): void {
    applyTheme(theme.value === 'dark' ? 'light' : 'dark')
  }

  return { theme, toggle, setTheme: applyTheme }
}

if (typeof document !== 'undefined') {
  applyTheme(readInitial())
}
import type { Router } from 'vue-router'

import { useAuthStore } from '@/stores/auth'
import { useSystemStore } from '@/stores/system'

export function setupGuards(router: Router): void {
  router.beforeEach(async (to) => {
    const auth = useAuthStore()

    if (to.meta.requiresAuth && !auth.isAuthenticated) {
      return { name: 'login', query: { redirect: to.fullPath } }
    }
    if (to.meta.guestOnly && auth.isAuthenticated) {
      return { name: 'chat' }
    }

    // M8：管理台仅管理员可进；非管理员显示无权限页（不静默跳走）。
    if (to.meta.requiresAdmin && auth.isAuthenticated) {
      if (!auth.user) await auth.restore()
      if (!auth.isAdmin) return { name: 'admin-forbidden' }
    }

    // 后端能力关闭的页面直接退回对话；M1 不请求 /agents、/tasks 等未注册端点。
    if (to.meta.capability && auth.isAuthenticated) {
      const system = useSystemStore()
      await system.load()
      if (system.loaded && !system.enabled(to.meta.capability)) {
        return { name: 'chat', query: { blocked: String(to.name ?? '') } }
      }
    }
    return true
  })

  router.afterEach((to) => {
    const title = to.meta.title
    document.title = title ? `${title} · Agent Hub` : 'Agent Hub'
  })
}
