    background 0.12s,
    color 0.12s,
    border-color 0.12s;
}

.admin-shell .icon-btn:hover {
  background: var(--surface-2);
  color: var(--ink);
  border-color: var(--line-2);
}

.admin-shell .icon-btn .ic {
  width: 15px;
  height: 15px;
}

.admin-shell .topbar-avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: 28px;
  height: 28px;
  margin-left: 2px;
  padding: 0;
  border-radius: 50%;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-mono);
  font-size: 9px;
}

.admin-shell .admin-account-pop {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 40;
  width: 196px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  box-shadow: var(--shadow-md);
}

.admin-shell .account-pop-head {
  padding: 7px 8px 9px;
  border-bottom: 1px solid var(--line-2);
}

.admin-shell .account-pop-head b {
  display: block;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--ink);
}

.admin-shell .account-pop-head small {
  display: block;
  margin-top: 2px;
  color: var(--ink-3);
  font-size: 9px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-shell .account-pop-item {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  height: 29px;
  padding: 0 8px;
  border-radius: 4px;
  color: var(--ink-2);
  font-size: 10.5px;
  text-align: left;
}

.admin-shell .account-pop-item:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.admin-shell .account-pop-item .ic {
  width: 13px;
  height: 13px;
  color: var(--ink-3);
}

.admin-shell .account-pop-item.is-danger {
  color: var(--red);
}

.admin-shell .account-pop-item.is-danger .ic {
  color: var(--red);
}

/* ---------------------------------------------------------------- page scaffold */
.admin-shell .admin-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  outline: none;
}

.admin-shell .admin-page {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 28px 34px 64px;
}

.admin-shell .admin-page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}

.admin-shell .page-title {
  font-size: 23px;
  font-weight: 650;
  letter-spacing: -0.022em;
  line-height: 1.2;
}

.admin-shell .page-sub {
  margin-top: 5px;
  font-size: 11.5px;
  line-height: 1.6;
  color: var(--ink-3);
  max-width: 68ch;
}

.admin-shell .head-actions {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: none;
  flex-wrap: wrap;
}

.admin-shell .prototype-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 14px;
  padding: 9px 12px;
  border: 1px solid var(--amber-soft);
  border-radius: 6px;
  background: var(--amber-soft);
  font-size: 10.5px;
  line-height: 1.6;
  color: var(--amber-text);
}

.admin-shell .prototype-note .ic {
  width: 14px;
  height: 14px;
  flex: none;
  margin-top: 1px;
}

.admin-shell .prototype-note .text-link {
  margin-left: auto;
  flex: none;
  white-space: nowrap;
  color: var(--amber-text);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.admin-shell .generated-line {
  margin-top: 12px;
  color: var(--ink-3);
  font-size: 9.5px;
}

/* ---------------------------------------------------------------- buttons */
.admin-shell .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 30px;
  padding: 0 11px;
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  transition:
    background 0.12s,
    color 0.12s,
    border-color 0.12s;
}

.admin-shell .btn .ic {
  width: 13px;
  height: 13px;
}

.admin-shell .btn-primary {
  background: var(--btn-bg);
  color: var(--btn-fg);
}

.admin-shell .btn-primary:hover {
  background: var(--prussian);
  color: var(--surface);
}

html[data-theme='dark'] .admin-shell .btn-primary:hover {
  background: var(--amber);
  color: #11181d;
}

.admin-shell .btn-outline {
  border-color: var(--line);
  background: var(--surface);
  color: var(--ink-2);
}

.admin-shell .btn-outline:hover {
  border-color: var(--ink-3);
  color: var(--ink);
  background: var(--surface-2);
}

.admin-shell .btn-ghost {
  border-color: transparent;
  background: transparent;
  color: var(--ink-2);
}

.admin-shell .btn-ghost:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.admin-shell .btn-danger {
  background: var(--red-soft);
  color: var(--red);
}

.admin-shell .btn-sm {
  height: 25px;
  padding: 0 8px;
  font-size: 10px;
  border-radius: 3px;
}

.admin-shell .btn-sm .ic {
  width: 11px;
  height: 11px;
}

.admin-shell .btn[disabled] {
  opacity: 0.42;
  cursor: not-allowed;
}

.admin-shell .text-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--prussian);
  font-size: 10px;
}

.admin-shell .text-link:hover {
  text-decoration: underline;
  text-underline-offset: 2px;
}

.admin-shell .text-link .ic {
  width: 10px;
  height: 10px;
}

.admin-shell .text-link.is-danger {
  color: var(--red);
}

.admin-shell .text-link[disabled] {
  color: var(--ink-3);
  cursor: not-allowed;
  text-decoration: none;
}

/* ---------------------------------------------------------------- status / badges */
.admin-shell .st {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 19px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 3px;
  font-size: 9px;
  font-weight: 500;
  white-space: nowrap;
}

.admin-shell .st .dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
}

.admin-shell .st-ok {
  background: var(--green-soft);
  color: var(--green);
}

.admin-shell .st-ok .dot {
  background: var(--green);
}

.admin-shell .st-live {
  background: var(--amber-soft);
  color: var(--amber-text);
}

.admin-shell .st-live .dot {
  background: var(--amber);
}

.admin-shell .st-warn {
  background: var(--amber-soft);
  color: var(--amber-text);
}

.admin-shell .st-warn .dot {
  background: var(--amber);
}

.admin-shell .st-error {
  background: var(--red-soft);
  color: var(--red);
}

.admin-shell .st-error .dot {
  background: var(--red);
}

.admin-shell .st-muted {
  background: var(--surface-2);
  color: var(--ink-3);
  border-color: var(--line-2);
}

.admin-shell .st-muted .dot {
  background: var(--ink-3);
}

@keyframes admin-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

.admin-shell .st-live .dot {
  animation: admin-pulse 2.4s ease-in-out infinite;
}

.admin-shell .role-badge {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 6px;
  border: 1px solid var(--line-2);
  border-radius: 3px;
  background: var(--surface-2);
  font-size: 9px;
  color: var(--ink-2);
  white-space: nowrap;
}

.admin-shell .role-badge.admin {
  background: var(--amber-soft);
  border-color: rgba(169, 116, 31, 0.2);
  color: var(--amber-text);
}

.admin-shell .role-badge.ops {
  background: var(--prussian-soft);
  border-color: rgba(23, 70, 94, 0.16);
  color: var(--prussian);
}

.admin-shell .role-badge.support {
  background: var(--green-soft);
  border-color: rgba(61, 106, 78, 0.14);
  color: var(--green);
}

.admin-shell .role-badge.editor {
  background: var(--mcp-soft);
  border-color: rgba(90, 78, 114, 0.16);
  color: var(--mcp);
}

.admin-shell .role-badge.auditor {
  background: var(--surface-2);
  color: var(--ink-3);
}

.admin-shell .type-chip {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 5px;
  border: 1px solid var(--line-2);
  border-radius: 3px;
  background: var(--surface-2);
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .type-chip.directory {
  background: var(--prussian-soft);
  border-color: transparent;
  color: var(--prussian);
}

.admin-shell .type-chip.button {
  background: var(--amber-soft);
  border-color: transparent;
  color: var(--amber-text);
}

.admin-shell .badge {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 5px;
  border-radius: 3px;
  background: var(--surface-2);
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .tag {
  display: inline-flex;
  align-items: center;
  height: 17px;
  padding: 0 4px;
  border: 1px solid var(--line-2);
  border-radius: 3px;
  background: var(--surface-2);
  font-family: var(--font-mono);
  font-size: 8px;
  color: var(--ink-3);
}

/* ---------------------------------------------------------------- metric strip */
.admin-shell .metric-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin: 18px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.admin-shell .metric {
  padding: 12px 16px 11px;
  border-right: 1px solid var(--line-2);
}

.admin-shell .metric:last-child {
  border-right: 0;
}

.admin-shell .metric-label {
  display: block;
  font-size: 9px;
  color: var(--ink-3);
  letter-spacing: 0.02em;
}

.admin-shell .metric-value {
  display: block;
  margin-top: 2px;
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 500;
  line-height: 1.2;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.admin-shell .metric-value small {
  margin-left: 4px;
  font-family: var(--font-sans);
  font-size: 9px;
  font-weight: 400;
  color: var(--ink-3);
}

.admin-shell .metric-foot {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 3px;
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .delta {
  color: var(--green);
  font-family: var(--font-mono);
}

.admin-shell .delta.is-warn {
  color: var(--amber-text);
}

.admin-shell .delta.is-bad {
  color: var(--red);
}

/* ---------------------------------------------------------------- panels */
.admin-shell .grid-2 {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  gap: 14px;
  margin-top: 14px;
}

.admin-shell .panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.admin-shell .panel-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-height: 44px;
  padding: 9px 14px;
  border-bottom: 1px solid var(--line-2);
}

.admin-shell .panel-head h2 {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: -0.005em;
}

.admin-shell .panel-head p {
  margin-top: 1px;
  font-size: 9.5px;
  color: var(--ink-3);
}

.admin-shell .panel-meta {
  font-size: 9px;
  color: var(--ink-3);
}

.admin-shell .panel-head .spacer {
  flex: 1;
}

.admin-shell .panel-body {
  padding: 14px;
}

.admin-shell .panel-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-top: 1px solid var(--line-2);
  background: var(--surface-2);
  font-size: 9px;
  color: var(--ink-3);
}

/* status list */
.admin-shell .status-list {
  display: flex;
  flex-direction: column;
}

.admin-shell .status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-2);
  font-size: 10.5px;
}

.admin-shell .status-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.admin-shell .status-row:first-child {
  padding-top: 0;
}

.admin-shell .status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex: none;
}

.admin-shell .status-dot.ok {
  background: var(--green);
}

.admin-shell .status-dot.warn {
  background: var(--amber);
}

.admin-shell .status-dot.bad {
  background: var(--red);
}

.admin-shell .status-name {
  flex: 1;
  color: var(--ink-2);
}

.admin-shell .status-meta {
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .status-state {
  font-size: 9px;
  color: var(--green);
  white-space: nowrap;
}

.admin-shell .status-state.warn {
  color: var(--amber-text);
}

.admin-shell .status-state.bad {
  color: var(--red);
}

/* recent audit mini */
.admin-shell .audit-mini {
  display: flex;
  flex-direction: column;
}

.admin-shell .audit-mini-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-2);
}

.admin-shell .audit-mini-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.admin-shell .audit-mini-row:first-child {
  padding-top: 0;
}

.admin-shell .audit-mini-time {
  width: 58px;
  flex: none;
  padding-top: 2px;
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .audit-mini-main {
  flex: 1;
  min-width: 0;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--ink-3);
}

.admin-shell .audit-mini-main b {
  font-weight: 550;
  color: var(--ink-2);
}

.admin-shell .audit-mini-res {
  margin-top: 2px;
  font-family: var(--font-mono);
  font-size: 8.5px;
  color: var(--ink-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* todo */
.admin-shell .todo-list {
  display: flex;
  flex-direction: column;
}

.admin-shell .todo-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line-2);
  font-size: 10.5px;
  color: var(--ink-2);
}

.admin-shell .todo-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.admin-shell .todo-row:first-child {
  padding-top: 0;
}

.admin-shell .todo-row .ic {
  width: 14px;
  height: 14px;
  color: var(--ink-3);
}

.admin-shell .todo-row b {
  font-family: var(--font-mono);
  font-weight: 500;
  color: var(--ink);
  font-size: 10px;
}

.admin-shell .todo-row .spacer {
  flex: 1;
}

.admin-shell .todo-row .text-link {
  flex: none;
}

/* ---------------------------------------------------------------- toolbar / forms */
.admin-shell .toolbar {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
  margin: 14px 0 10px;
}

.admin-shell .summary-line {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 14px;
  font-size: 10px;
  color: var(--ink-3);
}

.admin-shell .summary-line b {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-2);
}

.admin-shell .summary-line .sep {
  opacity: 0.45;
}

.admin-shell .search-field {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 29px;
  min-width: 210px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface);
}

.admin-shell .search-field .ic {
  width: 13px;
  height: 13px;
  color: var(--ink-3);
  flex: none;
}

.admin-shell .search-field input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  font: inherit;
  font-size: 10.5px;
  color: var(--ink);
}

.admin-shell .search-field input::placeholder {
  color: var(--ink-3);
}

.admin-shell .select,
.admin-shell .input,
.admin-shell .textarea {
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-size: 10.5px;
  outline: none;
  transition: border-color 0.12s;
}

.admin-shell .select:focus,
.admin-shell .input:focus,
.admin-shell .textarea:focus {
  border-color: var(--ink-3);
}

.admin-shell .select {
  cursor: pointer;
}

.admin-shell .textarea {
  height: auto;
  min-height: 70px;
  padding: 7px 8px;
  resize: vertical;
  line-height: 1.55;
}

.admin-shell .field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.admin-shell .field > span {
  font-size: 9px;
  color: var(--ink-3);
}

.admin-shell .field > small {
  font-size: 8.5px;
  color: var(--ink-3);
}

.admin-shell .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 11px;
}

.admin-shell .field-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line-2);
}

.admin-shell .field-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.admin-shell .field-row:first-child {
  padding-top: 0;
}

.admin-shell .field-row-main {
  min-width: 0;
}

.admin-shell .field-row-main b {
  display: block;
  font-size: 10.5px;
  font-weight: 550;
  color: var(--ink-2);
}

.admin-shell .field-row-main small {
  display: block;
  margin-top: 1px;
  font-size: 9px;
  color: var(--ink-3);
  line-height: 1.5;
}

.admin-shell .seg {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  padding: 2px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: var(--surface);
}

.admin-shell .seg button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 23px;
  padding: 0 8px;
  border-radius: 3px;
  font-size: 9.5px;
  color: var(--ink-3);
  white-space: nowrap;
  transition:
    background 0.12s,
    color 0.12s;
}

.admin-shell .seg button:hover {
  color: var(--ink);
}

.admin-shell .seg button.is-active {
  background: var(--surface-2);
  color: var(--ink);
  font-weight: 550;
}

.admin-shell .seg button .count {
  font-family: var(--font-mono);
  font-size: 8px;
  color: var(--ink-3);
}

/* switch */
.admin-shell .switch {
  position: relative;
  display: inline-flex;
  flex: none;
  width: 30px;
  height: 17px;
  cursor: pointer;
}

.admin-shell .switch input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.admin-shell .switch span {
  position: absolute;
  inset: 0;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: var(--line-2);
  transition:
    background 0.15s,
    border-color 0.15s;
}

.admin-shell .switch span::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: 0 1px 1px rgba(20, 27, 32, 0.18);
  transition: transform 0.15s;
}

.admin-shell .switch input:checked + span {
  background: var(--prussian);
  border-color: var(--prussian);
}

.admin-shell .switch input:checked + span::after {
  transform: translateX(13px);
}

.admin-shell .switch input:focus-visible + span {
  outline: 2px solid var(--prussian);
  outline-offset: 2px;
}

/* ---------------------------------------------------------------- tables */
.admin-shell .table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
}

.admin-shell .data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 10.5px;
  min-width: 720px;
}

.admin-shell .data-table th {
  height: 34px;
  padding: 0 11px;
