 * 仅用于 AdminLayout 内部页面与 /admin/forbidden；通过 index.css 引入一次。
 */

/* ---------------------------------------------------------------- tokens */
.admin-shell {
  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB',
    'Noto Sans SC', 'Source Han Sans SC', 'Microsoft YaHei', sans-serif;
