    monospace;

  --paper: #f0efe8;
  --paper-2: #e9e7dd;
  --surface: #fbfaf5;
  --surface-2: #f4f3ec;
  --ink: #141b20;
  --ink-2: #4f5b63;
  --ink-3: #606b72;
  --line: #d7d5c9;
  --line-2: #e3e1d6;

  --prussian: #17465e;
  --prussian-soft: #e4ecef;
  --amber: #a9741f;
  --amber-text: #8a5d14;
  --amber-soft: #f3e9d3;
  --red: #9c3a2b;
  --red-soft: #f6e5e0;
  --green: #3d6a4e;
  --green-soft: #e4ede6;
  --mcp: #5a4e72;
  --mcp-soft: #ece8f1;

  --btn-bg: #141b20;
  --btn-fg: #fbfaf5;

  --shadow-sm: 0 1px 2px rgba(20, 27, 32, 0.05);
  --shadow-md: 0 1px 2px rgba(20, 27, 32, 0.04), 0 10px 28px -18px rgba(20, 27, 32, 0.35);
  --shadow-lg: 0 20px 50px -30px rgba(20, 27, 32, 0.45);

  --rail: #11181d;
  --rail-2: #0c1216;
  --rail-text: #ecebe4;
  --rail-muted: rgba(236, 235, 228, 0.55);
  --rail-faint: rgba(236, 235, 228, 0.36);
  --rail-line: rgba(236, 235, 228, 0.09);
  --rail-active: rgba(236, 235, 228, 0.075);
  --rail-amber: #d4a04a;

  display: grid;
  grid-template-columns: 252px minmax(0, 1fr);
  height: 100vh;
  overflow: hidden;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 13.5px;
  line-height: 1.5;
