  --red: #de907e;
  --red-soft: rgba(222, 144, 126, 0.12);
  --green: #8dbba0;
  --green-soft: rgba(141, 187, 160, 0.12);
  --mcp: #b3a4c9;
  --mcp-soft: rgba(179, 164, 201, 0.12);

  --btn-bg: #e8e7df;
  --btn-fg: #10171b;

  --shadow-sm: 0 1px 0 rgba(255, 255, 255, 0.03);
  --shadow-md: 0 1px 0 rgba(255, 255, 255, 0.03), 0 16px 40px -24px rgba(0, 0, 0, 0.9);
  --shadow-lg: 0 28px 60px -32px rgba(0, 0, 0, 0.95);

