  position: fixed;
  right: 0;
  top: 0;
  bottom: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  width: min(520px, 96vw);
  background: var(--surface);
  border-left: 1px solid var(--line);
  box-shadow: -24px 0 48px -32px rgba(0, 0, 0, 0.45);
  transform: translateX(102%);
  transition: transform 0.24s ease;
  outline: none;
