  --line: #d7d5c9;
  --line-2: #e3e1d6;

  --prussian: #17465e;
  --prussian-soft: #e4ecef;
  --amber: #a9741f;
  --amber-text: #8a5d14;
  --amber-soft: #f3e9d3;
  --red: #9c3a2b;
  --red-soft: #f6e5e0;
  --green: #3d6a4e;
  --green-soft: #e4ede6;
