  .admin-shell .metric:nth-child(5) {
    border-top: 1px solid var(--line-2);
  }

  .admin-shell .metric:nth-child(5) {
    border-right: 0;
  }

  .admin-shell .form-grid,
  .admin-shell .settings-grid {
    grid-template-columns: 1fr;
  }

  .admin-shell .drawer {
    width: 100vw;
  }

  .admin-shell .toolbar {
    gap: 6px;
  }

  .admin-shell .search-field {
    flex: 1;
    min-width: 150px;
  }

  .admin-shell .data-table {
    font-size: 10px;
  }

  .admin-shell .admin-page-head .head-actions .btn {
    flex: 1;
  }

  .admin-shell .page-title {
    font-size: 21px;
  }

  .admin-shell .panel-head {
    padding: 8px 12px;
  }

  .admin-shell .panel-body {
    padding: 12px;
  }

  .admin-shell .role-item {
    padding: 7px;
  }
}

