await page.goto('http://127.0.0.1:5174/login')
await page.getByPlaceholder('you@example.com').fill('admin@example.com')
await page.getByPlaceholder('至少 8 位').fill('12345678')
await page.getByRole('button', { name: '登录', exact: true }).click()
await page.waitForURL(/\/chat/)
for (const path of ['/admin','/admin/users','/admin/roles','/admin/menus','/admin/dictionaries','/admin/audit','/admin/settings','/admin/forbidden']) {
  await page.goto('http://127.0.0.1:5174'+path)
  await page.waitForTimeout(1600)
  const results = await new AxeBuilder({ page }).analyze()
  const bad = results.violations.filter(v => v.impact === 'serious' || v.impact === 'critical')
  console.log(path, 'violations:', results.violations.map(v=>`${v.id}(${v.impact})`).join(', ') || 'none')
  for (const v of bad) console.log('  ', v.id, v.nodes.slice(0,2).map(n=>n.target.join(' ')))
}
await browser.close()
