const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await context.newPage()
await page.goto('http://127.0.0.1:5174/login')
await page.getByPlaceholder('you@example.com').fill('admin@example.com')
await page.getByPlaceholder('至少 8 位').fill('12345678')
await page.getByRole('button', { name: '登录', exact: true }).click()
await page.waitForURL(/\/chat/)
for (const path of ['/admin','/admin/users','/admin/settings','/admin/forbidden']) {
  await page.goto('http://127.0.0.1:5174'+path)
  await page.waitForTimeout(1300)
  const results = await new AxeBuilder({ page }).analyze()
  const mine = results.violations.filter(v => v.nodes.some(n => !n.target.join(' ').includes('panel-entry-btn')))
  console.log(path, mine.map(v=>v.id).join(',') || 'clean')
}
await context.close(); await browser.close()
EOF", "description": "最终 axe 抽查管理台页面", "timeoutMs": 180000}

